use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut keys: Vec<int> = []
    let mut left: Vec<int> = []
    let mut right: Vec<int> = []
    let mut root: int = -1
    for line in text.lines() {
        let parts: Vec<string> = line.trim().split(" ").collect()
        if parts.len() == 0 { continue }
        let cmd = parts[0]
        let mut x: int = 0
        if parts.len() > 1 { x = parts[1].parse::<int>().unwrap_or(0) }
        if cmd == "insert" {
            if root == -1 {
                keys.push(x)
                left.push(-1)
                right.push(-1)
                root = 0
                println("ok")
            } else {
                let mut cur: int = root
                let mut done = false
                while !done {
                    let k = keys[cur as usize]
                    if x == k {
                        println("dup")
                        done = true
                    } else {
                        let nxt = if x < k { left[cur as usize] } else { right[cur as usize] }
                        if nxt == -1 {
                            let id: int = keys.len() as int
                            keys.push(x)
                            left.push(-1)
                            right.push(-1)
                            if x < k { left[cur as usize] = id } else { right[cur as usize] = id }
                            println("ok")
                            done = true
                        } else {
                            cur = nxt
                        }
                    }
                }
            }
        } else if cmd == "contains" {
            let mut cur: int = root
            let mut found = false
            while cur != -1 && !found {
                let k = keys[cur as usize]
                if k == x { found = true }
                else if x < k { cur = left[cur as usize] }
                else { cur = right[cur as usize] }
            }
            if found { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let mut cur: int = root
            let mut parent: int = -1
            while cur != -1 && keys[cur as usize] != x {
                parent = cur
                if x < keys[cur as usize] { cur = left[cur as usize] } else { cur = right[cur as usize] }
            }
            if cur == -1 {
                println("missing")
            } else {
                let c = cur as usize
                if left[c] != -1 && right[c] != -1 {
                    let mut sp: int = cur
                    let mut s: int = right[c]
                    while left[s as usize] != -1 {
                        sp = s
                        s = left[s as usize]
                    }
                    keys[c] = keys[s as usize]
                    if sp == cur { right[sp as usize] = right[s as usize] }
                    else { left[sp as usize] = right[s as usize] }
                } else {
                    let child = if left[c] != -1 { left[c] } else { right[c] }
                    if parent == -1 { root = child }
                    else if left[parent as usize] == cur { left[parent as usize] = child }
                    else { right[parent as usize] = child }
                }
                println("ok")
            }
        } else if cmd == "inorder" {
            if root == -1 {
                println("<empty>")
            } else {
                let mut stack: Vec<int> = []
                let mut out: Vec<string> = []
                let mut cur: int = root
                while cur != -1 || stack.len() > 0 {
                    while cur != -1 {
                        stack.push(cur)
                        cur = left[cur as usize]
                    }
                    let n = stack.pop().unwrap_or(0)
                    out.push("${keys[n as usize]}")
                    cur = right[n as usize]
                }
                println(out.join(" "))
            }
        } else if cmd == "height" {
            let mut best: int = 0
            if root != -1 {
                let mut st: Vec<int> = [root]
                let mut dp: Vec<int> = [1]
                while st.len() > 0 {
                    let n = st.pop().unwrap_or(0)
                    let d = dp.pop().unwrap_or(0)
                    if d > best { best = d }
                    if left[n as usize] != -1 {
                        st.push(left[n as usize])
                        dp.push(d + 1)
                    }
                    if right[n as usize] != -1 {
                        st.push(right[n as usize])
                        dp.push(d + 1)
                    }
                }
            }
            println("${best}")
        } else if cmd == "min" || cmd == "max" {
            if root == -1 {
                println("empty")
            } else {
                let mut cur: int = root
                if cmd == "min" {
                    while left[cur as usize] != -1 { cur = left[cur as usize] }
                } else {
                    while right[cur as usize] != -1 { cur = right[cur as usize] }
                }
                println("${keys[cur as usize]}")
            }
        }
    }
}

